#include <vector>
#include <algorithm>

class Solution {
    int lis_2d(std::vector<std::vector<int>>& pts) {
        if (pts.empty()) return 0;
        std::sort(pts.begin(), pts.end(), [](const auto& a, const auto& b) {
            if (a[0] != b[0]) return a[0] < b[0];
            return a[1] > b[1];
        });
        std::vector<int> tails;
        for (const auto& p : pts) {
            int y = p[1];
            auto it = std::lower_bound(tails.begin(), tails.end(), y);
            if (it == tails.end()) tails.push_back(y);
            else *it = y;
        }
        return tails.size();
    }
public:
    int maxPathLength(std::vector<std::vector<int>>& coordinates, int k) {
        int kx = coordinates[k][0], ky = coordinates[k][1];
        std::vector<std::vector<int>> left_pts, right_pts;
        for (const auto& p : coordinates) {
            if (p[0] < kx && p[1] < ky) left_pts.push_back(p);
            else if (p[0] > kx && p[1] > ky) right_pts.push_back(p);
        }
        return lis_2d(left_pts) + 1 + lis_2d(right_pts);
    }
