import java.util.*;

class Solution {
    public int maxPathLength(int[][] coordinates, int k) {
        int kx = coordinates[k][0], ky = coordinates[k][1];
        List<int[]> leftPts = new ArrayList<>();
        List<int[]> rightPts = new ArrayList<>();

        for (int[] p : coordinates) {
            if (p[0] < kx && p[1] < ky) leftPts.add(p);
            else if (p[0] > kx && p[1] > ky) rightPts.add(p);
        }

        return lis2D(leftPts) + 1 + lis2D(rightPts);
    }

    private int lis2D(List<int[]> pts) {
        if (pts.isEmpty()) return 0;
        pts.sort((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(b[1], a[1]);
        });

        List<Integer> tails = new ArrayList<>();
        for (int[] p : pts) {
            int y = p[1];
            int idx = Collections.binarySearch(tails, y);
            if (idx < 0) idx = -(idx + 1);
            if (idx == tails.size()) tails.add(y);
            else tails.set(idx, y);
        }
        return tails.size();
    }
}

var maxPathLength = function(coordinates, k) {
    const [kx, ky] = coordinates[k];
    const leftPts = [];
    const rightPts = [];

    for (const p of coordinates) {
        if (p[0] < kx && p[1] < ky) leftPts.push(p);
        else if (p[0] > kx && p[1] > ky) rightPts.push(p);
    }

    function lis2D(pts) {
        if (pts.length === 0) return 0;
        pts.sort((a, b) => {
            if (a[0] !== b[0]) return a[0] - b[0];
            return b[1] - a[1];
        });

        const tails = [];
        for (const p of pts) {
            const y = p[1];
            let low = 0, high = tails.length;
            while (low < high) {
                const mid = (low + high) >> 1;
                if (tails[mid] < y) low = mid + 1;
                else high = mid;
            }
            if (low === tails.length) tails.push(y);
            else tails[low] = y;
        }
        return tails.length;
    }

    return lis2D(leftPts) + 1 + lis2D(rightPts);
};
